1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
16	 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
17	 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
18	 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
19	 * validation, is the authoritative implementation of the required-field rule.
20	 *
21	 * <p>The address is normalized (see {@link OwnerAddress}) before the required-field check, so an
22	 * address that is blank once whitespace is collapsed is rejected as missing. The normalized value is
23	 * written back onto the body so the normalized, abbreviation-expanded address is what gets stored,
24	 * returned and compared for household matching.
25	 *
26	 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
27	 * value that cannot form a valid E.164 number is rejected with a 400 via
28	 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
29	 * gets stored and returned.
30	 *
31	 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
32	 * syntactically valid address; otherwise the create is rejected with a 400 via
33	 * {@link OwnerEmailInvalidException}. A valid email is lower-cased and written back onto the body so
34	 * the lower-cased value is what gets stored and returned. The validated body is republished for
35	 * {@link BuildOwner}.
36	 */
37	public class ValidateOwner {
38	
39	    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
40	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
41	
42	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
43	            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
44	            OwnerEmailInvalidException {
45	        List<String> missing = new ArrayList<>();
46	        if (isBlank(request.getFirstName())) {
47	            missing.add("firstName");
48	        }
49	        if (isBlank(request.getLastName())) {
50	            missing.add("lastName");
51	        }
52	        String address = OwnerAddress.normalize(request.getAddress());
53	        if (address.isEmpty()) {
54	            missing.add("address");
55	        }
56	        if (isBlank(request.getCity())) {
57	            missing.add("city");
58	        }
59	        if (isBlank(request.getTelephone())) {
60	            missing.add("telephone");
61	        }
62	        if (!missing.isEmpty()) {
63	            throw new OwnerFieldsMissingException(missing);
64	        }
65	        request.setAddress(address);
66	        String e164 = OwnerTelephone.toE164(request.getTelephone());
67	        if (e164 == null) {
68	            throw new OwnerTelephoneInvalidException(request.getTelephone());
69	        }
70	        request.setTelephone(e164);
71	
72	        String email = request.getEmail();
73	        if (email != null) {
74	            if (!EMAIL.matcher(email).matches()) {
75	                throw new OwnerEmailInvalidException(email);
76	            }
77	            request.setEmail(email.toLowerCase());
78	        }
79	
80	        validated.set(request);
81	    }
82	
83	    private static boolean isBlank(String value) {
84	        return value == null || value.isBlank();
85	    }
86	}
