5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerDailyLimitException;
10	
11	/**
12	 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 429 via
13	 * {@link OwnerDailyLimitException} when the maximum number of owners ({@value #MAX_OWNERS_PER_DAY})
14	 * already share the new owner's effective registration date, as determined by their
15	 * {@code registrationDate}. That effective date is the request's supplied date, or the server's
16	 * current date when omitted, rolled forward off any weekend to a business day (see {@link BusinessDay}),
17	 * so the limit counts owners per adjusted business day. The new owner is still unsaved — and is itself
18	 * dated that same business day (see {@link BuildOwner}) — so it is not counted against the limit.
19	 */
20	public class CheckOwnerDailyLimit {
21	
22	    /** At most this many owners may be created in a single day; the create of one more is rejected. */
23	    static final int MAX_OWNERS_PER_DAY = 100;
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws OwnerDailyLimitException {
27	        LocalDate businessDay = BusinessDay.effective(request.getRegistrationDate());
28	        int count = 0;
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (businessDay.equals(existing.getRegistrationDate())) {
31	                count++;
32	            }
33	        }
34	        if (count >= MAX_OWNERS_PER_DAY) {
35	            throw new OwnerDailyLimitException(businessDay, count);
36	        }
37	    }
38	}
