3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after {@link BuildOwner} and before {@link SaveOwner} on {@code POST /api/owners}. Assigns the
9	 * new owner's {@code customerCode} formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
10	 * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters of the
11	 * owner's lastName and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
12	 * owners already in that city (e.g. {@code LON-SMI-0007}). The owner is still unsaved, so the count
13	 * excludes it and the per-city sequence advances by one per create.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city = owner.getCity();
19	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
20	        String lastName = owner.getLastName();
21	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
22	        long sequence = ownerRepository.findAll().stream()
23	            .filter(existing -> city.equals(existing.getCity()))
24	            .count() + 1;
25	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
26	    }
27	}
