1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * The single definition of how an owner's {@code address} is normalized. Applied whenever an owner is
8	 * created (see {@link ValidateOwner}, which stores and returns the normalized value) and used by every
9	 * comparison of addresses (see {@link OwnerHousehold}), so stored values and household matching stay
10	 * consistent.
11	 *
12	 * <p>Normalization: strip surrounding whitespace and collapse internal runs to a single space,
13	 * upper-case, then expand common abbreviations token-by-token ({@code ST}→{@code STREET},
14	 * {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). A value that is blank after this is normalized
15	 * to the empty string, which {@link ValidateOwner} treats as a missing required field.
16	 */
17	public final class OwnerAddress {
18	
19	    /** Whole-token abbreviation expansions, keyed by the upper-cased token. */
20	    private static final Map<String, String> ABBREVIATIONS = Map.of(
21	            "ST", "STREET",
22	            "RD", "ROAD",
23	            "AVE", "AVENUE");
24	
25	    private OwnerAddress() {
26	    }
27	
28	    public static String normalize(String value) {
29	        if (value == null) {
30	            return "";
31	        }
32	        String collapsed = value.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
33	        if (collapsed.isEmpty()) {
34	            return "";
35	        }
36	        String[] tokens = collapsed.split(" ");
37	        StringBuilder result = new StringBuilder(collapsed.length());
38	        for (int i = 0; i < tokens.length; i++) {
39	            if (i > 0) {
40	                result.append(' ');
41	            }
42	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
43	        }
44	        return result.toString();
45	    }
46	}
