1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Single source of truth for the "E.164 telephone" concept shared by the create pipeline:
5	 * {@link ValidateOwner} converts the submitted value to E.164 before storing it, and
6	 * {@link CheckOwnerTelephoneUnique} converts stored owner values the same way when comparing for
7	 * duplicates. Keeping the rule here ensures the value that gets stored and the value compared for
8	 * uniqueness can never silently diverge.
9	 */
10	public final class OwnerTelephone {
11	
12	    private OwnerTelephone() {
13	    }
14	
15	    /**
16	     * Convert a raw telephone to E.164 form, or return {@code null} if it cannot form a valid E.164
17	     * number. Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps its country code;
18	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from
19	     * the national digits. The result must have 8 to 15 digits after the {@code '+'}.
20	     */
21	    public static String toE164(String value) {
22	        if (value == null) {
23	            return null;
24	        }
25	        // Strip spaces, dashes and brackets (round and square).
26	        String cleaned = value.replaceAll("[\\s()\\[\\]-]", "");
27	        String digits;
28	        if (cleaned.startsWith("+")) {
29	            digits = cleaned.substring(1);
30	        }
31	        else {
32	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
33	            digits = "61" + national;
34	        }
35	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
36	    }
37	}
