1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day rules for owner registration on {@code POST /api/owners}. The effective registration
8	 * date must fall on a business day: when it is a Saturday or Sunday it rolls forward to the following
9	 * Monday. The effective date is the one supplied in the request, or the server's current date when the
10	 * request omits it; either way the same roll-forward applies, so every value derived from the
11	 * registration date (the membership number's year segment, the per-day create-limit bucket) is computed
12	 * from the adjusted date.
13	 */
14	final class BusinessDay {
15	
16	    private BusinessDay() {
17	    }
18	
19	    /** Rolls a weekend date forward to the following Monday; a weekday is returned unchanged. */
20	    static LocalDate rollForward(LocalDate date) {
21	        DayOfWeek dow = date.getDayOfWeek();
22	        if (dow == DayOfWeek.SATURDAY) {
23	            return date.plusDays(2);
24	        }
25	        if (dow == DayOfWeek.SUNDAY) {
26	            return date.plusDays(1);
27	        }
28	        return date;
29	    }
30	
31	    /**
32	     * The effective, business-day registration date for a create: the supplied date when present,
33	     * otherwise the server's current date, rolled forward off any weekend.
34	     */
35	    static LocalDate effective(LocalDate supplied) {
36	        return rollForward(supplied != null ? supplied : LocalDate.now());
37	    }
38	}
